import { Component, HostListener } from '@angular/core';
import { UploadService } from '../../../services/upload/upload.service';
import { MatSelectModule } from '@angular/material/select';
import { uploadfileComponent } from '../uploadfile/uploadfile.component';
import { uploadhistoryComponent } from '../uploadhistory/uploadhistory.component';
import { UploadreportComponent } from '../uploadreport/uploadreport.component';
import { ChoosenfilesComponent } from '../choosenfiles/choosenfiles.component';
import { UploadingComponent } from '../uploading/uploading.component';
import { CommonModule } from '@angular/common';
import { MatMenuModule } from '@angular/material/menu';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { ActivatedRoute } from '@angular/router';
import { FileStorageService } from '../../../services/upload/file-storage/file-storage.service';
import { caseDetailMDL, rowReportSummaryMDL } from '../../../interfaces/upload.interface';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { Title } from '@angular/platform-browser';
import { UserPermissionService } from '../../../../shared/services/user-permission/user-permission.service';

@Component({
  selector: 'app-uploadmanager',
  standalone: true,
  imports: [MatSelectModule, uploadfileComponent, uploadhistoryComponent, ChoosenfilesComponent, uploadhistoryComponent, CommonModule, MatMenuModule, IconComponent],
  templateUrl: './uploadmanager.component.html',
  styleUrl: './uploadmanager.component.scss'
})
export class UploadmanagerComponent {
  caseDetail: caseDetailMDL;
  report1 = 1;
  currentStep: string = 'S'; // S - Upload, L - List, U - Uploading
  nCaseid: string;
  isUser: boolean = false;
  nSectionid: string = null;


  // @HostListener('window:beforeunload', ['$event'])
  // unloadNotification($event: any): string {
  //     const confirmationMessage = 'Are you sure you want to leave this page?';
  //     $event.returnValue = confirmationMessage;
  //     return confirmationMessage;
  // }

  row_sessions: rowReportSummaryMDL[] = [];
  constructor(public us: UploadService, private route: ActivatedRoute, public store: FileStorageService, private cfs: CommonfunctionService, private titleService: Title,
    private userPermissions: UserPermissionService
  ) {
    let params = this.route.snapshot.params;
    params = JSON.parse(atob(params["id"]));
    this.initList(params);


    this.row_sessions = this.store.getRowSessions();

  }

  async initList(params: any): Promise<void> {
    this.nCaseid = params.c;
    this.store.getSectionDetail(params.s);
    this.store.getBundleDetail(params.b);
    this.nSectionid = params.s;
    this.isUser = params?.type == 'user' ? true : false;
    this.store.getCaseDetail(params.c, this.nSectionid, this.isUser).then((res: caseDetailMDL) => {
      this.caseDetail = res;
    });
    this.userPermissions.userPermissionList(this.nCaseid);
  }

  UploadEvent(e: any) {
    if (e == 'DATA-RECIEVED') {
      this.currentStep = 'L';
    }
  }

  ngOnInit(): void {
    this.titleService.setTitle('Caseload');
  }

  FilesEvent(e: any) {

    if (e == 'RESET-UI') {
      this.currentStep = 'S';
    }
  }

  UploadingEvent(e: any) {

  }


  ngOnDestroy() {
  }

  onHistroyData(e: any) {
    if (e.event == 'GO-TO-REPORT') {
      this.goToreport(e.data)
    }
  }

  goToreport(x: any) {
    this.cfs.goto('/upload/uploadreport', { nUPid: x.nUPid, nCaseid: this.nCaseid });
  }


}